def process(wollaston_beach) -> pd.DataFrame:
    met_standards = wollaston_beach['Violation'].isin(['No', 'NO']).sum()
    total_tests = len(wollaston_beach)
    percentage = int((met_standards / total_tests) * 100) if total_tests > 0 else 0
    return pd.DataFrame({'percentage': [percentage], 'met_standards': [met_standards], 'total_tests': [total_tests]})
